-- Closes the related-term chip coverage gap surfaced on 2026-07-27:
-- 71 related_terms strings resolved to nothing, so their chips rendered muted.
--   Part 1: 8 near-misses to existing terms -> aliases
--   Part 2: 63 genuinely missing terms -> new rows
-- House style: plain-language definition, concrete example, related_terms that
-- themselves resolve. `arkline` entries describe the framework without exposing
-- component weights and avoid buy/sell framing.

-- ── Part 1: aliases for chips that already have a term ──────────────────────
UPDATE dictionary SET aliases = aliases || ARRAY['Risk-On / Risk-Off', 'Risk On / Risk Off'] WHERE slug = 'risk-on';
UPDATE dictionary SET aliases = aliases || ARRAY['Risk-Reward'] WHERE slug = 'risk-reward-ratio';
UPDATE dictionary SET aliases = aliases || ARRAY['QE'] WHERE slug = 'quantitative-easing';
UPDATE dictionary SET aliases = aliases || ARRAY['QT'] WHERE slug = 'quantitative-tightening';
UPDATE dictionary SET aliases = aliases || ARRAY['Fed'] WHERE slug = 'federal-reserve';
UPDATE dictionary SET aliases = aliases || ARRAY['M2'] WHERE slug = 'm2-money-supply';
UPDATE dictionary SET aliases = aliases || ARRAY['Bonds'] WHERE slug = 'bond';
UPDATE dictionary SET aliases = aliases || ARRAY['Correction'] WHERE slug = 'market-correction';

-- ── Part 2: new terms ───────────────────────────────────────────────────────
ON CONFLICT DO NOTHING;
